        // Talk ignored phrases
        const talkIgnoredInput = panel.querySelector("#minibia-bot-talk-ignored");
        if (talkIgnoredInput) {
            talkIgnoredInput.value = (bot.talk?.config?.ignoredPhrases || []).join(", ");
            talkIgnoredInput.addEventListener("change", saveTalkIgnoredPhrases);
            talkIgnoredInput.addEventListener("blur", saveTalkIgnoredPhrases);
        }

        //Talk main
        const talkEnabledInput = panel.querySelector("#minibia-bot-talk-enabled");
        const talkApiKeyInput = panel.querySelector("#minibia-bot-talk-api-key");
        const talkPromptInput = panel.querySelector("#minibia-bot-talk-prompt");

        // --- Load talk config into UI ---
        if (talkApiKeyInput) {
            talkApiKeyInput.value = bot.talk?.config?.apiKey || "";
        }
        if (talkPromptInput) {
            talkPromptInput.value = bot.talk?.config?.systemPrompt || "";
        }

        if (talkEnabledInput) {
            talkEnabledInput.checked = !!bot.talk?.status?.().running;
            talkEnabledInput.addEventListener("change", function () {
                // Disable the checkbox briefly to prevent rapid clicks
                this.disabled = true;

                const apiKey = talkApiKeyInput?.value?.trim() || "";
                const systemPrompt = talkPromptInput?.value?.trim() || bot.talk.config.systemPrompt || "";

                if (this.checked) {
                    // Save config first
                    bot.talk.updateConfig({
                        apiKey,
                        systemPrompt
                    });
                    const started = bot.talk.start();
                    if (!started) {
                        // If start failed, uncheck and show status
                        this.checked = false;
                        // The refresh will show the error
                    }
                } else {
                    bot.talk.stop();
                }

                refreshTalkStatus();
                this.disabled = false;
            });
        }

        // Cave bot waypoint actions
        const addBtn = panel.querySelector("#minibia-bot-cave-add");
        const moveUpBtn = panel.querySelector("#minibia-bot-cave-move-up");
        const moveDownBtn = panel.querySelector("#minibia-bot-cave-move-down");
        const delBtn = panel.querySelector("#minibia-bot-cave-delete-selected");
        if (addBtn) {
            addBtn.addEventListener("click", () => {
                const pos = bot.getPlayerPosition();
                if (!pos) {
                    bot.log("Cannot get player position.");
                    return;
                }
                const dirSelect = document.getElementById("minibia-bot-cave-direction");
                const standCheck = document.getElementById("minibia-bot-cave-stand");
                const ropeCheck = document.getElementById("minibia-bot-cave-rope");
                const shovelCheck = document.getElementById("minibia-bot-cave-shovel");
                const ladderCheck = document.getElementById("minibia-bot-cave-ladder");
                const dir = dirSelect ? dirSelect.value : "C";
                const offset = getDirectionOffset(dir);
                const x = pos.x + offset.dx;
                const y = pos.y + offset.dy;
                const z = pos.z;
                const stand = !!(standCheck && standCheck.checked);
                const rope = !!(ropeCheck && ropeCheck.checked);
                const shovel = !!(shovelCheck && shovelCheck.checked);
                const ladder = !!(ladderCheck && ladderCheck.checked);
                const label = stand ? "Stand" : (rope ? "Rope" : (shovel ? "Shovel" : ""));
                const waypoint = {
                    x,
                    y,
                    z,
                    label: label || undefined,
                    stand: stand,
                    rope: rope,
                    shovel: shovel,
                    ladder: ladder
                };
                const route = bot.cave.getRoute();
                let insertIndex = route.length; // append
                if (selectedWaypointIndex !== null && selectedWaypointIndex >= 0 && selectedWaypointIndex < route.length) {
                    insertIndex = selectedWaypointIndex + 1;
                }
                const added = bot.cave.addWaypoint(waypoint, insertIndex);
                if (added) {
                    bot.cave.setCurrentIndex(insertIndex);
                    selectedWaypointIndex = insertIndex;
                    // ... update label/script inputs ...
                    refreshCaveWaypointList();
                    refreshCaveStatus();
                    refreshCaveClosestStatus();
                    refreshCaveTransitionStatus();
                    refreshCavePresetControls();
                    // Force‑scroll to the new waypoint (even if cavebot is not running)
                    scrollToWaypointIndex(insertIndex, true);
                    bot.log("Waypoint added after selected index " + (insertIndex - 1) + " and set as current.");
                }
            });
        }
        if (moveUpBtn)
            moveUpBtn.addEventListener("click", () => moveSelectedWaypoint("up"));
        if (moveDownBtn)
            moveDownBtn.addEventListener("click", () => moveSelectedWaypoint("down"));
        if (delBtn)
            delBtn.addEventListener("click", deleteSelectedWaypoint);

        // ---- Move to Index ----
        const moveToIndexBtn = document.getElementById("minibia-bot-cave-move-to-index-btn");
        const moveToIndexInput = document.getElementById("minibia-bot-cave-move-to-index");
        const moveStatusLabel = document.getElementById("minibia-bot-cave-move-status");

        if (moveToIndexBtn && moveToIndexInput) {
            moveToIndexBtn.addEventListener("click", () => {
                const route = bot.cave.getRoute();
                if (!route.length) {
                    bot.log("No waypoints to move.");
                    if (moveStatusLabel)
                        moveStatusLabel.textContent = "No waypoints.";
                    return;
                }

                // Determine which waypoint to move (selected, or fallback to current)
                let fromIndex = selectedWaypointIndex;
                if (fromIndex === null || fromIndex < 0 || fromIndex >= route.length) {
                    const status = bot.cave.status();
                    if (status && typeof status.currentIndex === 'number') {
                        fromIndex = status.currentIndex;
                    } else {
                        bot.log("No waypoint selected. Click a waypoint first.");
                        if (moveStatusLabel)
                            moveStatusLabel.textContent = "Select a waypoint first.";
                        return;
                    }
                }

                const toIndex = parseInt(moveToIndexInput.value, 10);
                if (isNaN(toIndex) || toIndex < 0 || toIndex >= route.length) {
                    bot.log(`Invalid target index. Must be 0 - ${route.length - 1}.`);
                    if (moveStatusLabel)
                        moveStatusLabel.textContent = `Invalid (0-${route.length - 1})`;
                    return;
                }

                if (fromIndex === toIndex) {
                    bot.log("Waypoint is already at that index.");
                    if (moveStatusLabel)
                        moveStatusLabel.textContent = "Already there.";
                    return;
                }

                const success = bot.cave.moveWaypointToIndex(fromIndex, toIndex);
                if (success) {
                    selectedWaypointIndex = toIndex;
                    moveToIndexInput.value = toIndex;
                    if (moveStatusLabel)
                        moveStatusLabel.textContent = `Moved to ${toIndex}`;
                    refreshCaveWaypointList();
                    refreshCaveStatus();
                    refreshCaveClosestStatus();
                    refreshCaveTransitionStatus();
                    refreshCavePresetControls();
                    // Force‑scroll to the moved waypoint (even if cavebot is idle)
                    scrollToWaypointIndex(toIndex, true);
                    bot.log(`Moved waypoint to index ${toIndex}.`);
                } else {
                    bot.log("Failed to move waypoint.");
                    if (moveStatusLabel)
                        moveStatusLabel.textContent = "Move failed.";
                }
            });

            // Press Enter in the input to trigger the move
            moveToIndexInput.addEventListener("keydown", (e) => {
                if (e.key === "Enter") {
                    e.preventDefault();
                    moveToIndexBtn.click();
                }
            });
        }

        // Cave preset
        const presetSelect = panel.querySelector("#minibia-bot-cave-preset-select");
        const presetNew = panel.querySelector("#minibia-bot-cave-preset-new");
        const presetDelete = panel.querySelector("#minibia-bot-cave-preset-delete");
        if (presetSelect) {
            presetSelect.addEventListener("change", () => {
                const name = presetSelect.value;
                if (!name)
                    return;
                bot.cave.loadPreset(name);
                refreshCavePresetControls();
                refreshCaveStatus();
                refreshCaveClosestStatus();
                refreshCaveTransitionStatus();
                refreshCaveWaypointList();
            });
        }
        if (presetNew) {
            presetNew.addEventListener("click", () => {
                const name = window.prompt("Name the new cave preset:");
                if (name == null)
                    return;
                bot.cave.createPreset(name);
                refreshCavePresetControls();
                refreshCaveStatus();
                refreshCaveClosestStatus();
                refreshCaveTransitionStatus();
                refreshCaveWaypointList();
            });
        }
        if (presetDelete) {
            presetDelete.addEventListener("click", () => {
                const name = presetSelect?.value;
                if (!name)
                    return;
                bot.cave.deletePreset(name);
                refreshCavePresetControls();
                refreshCaveStatus();
                refreshCaveClosestStatus();
                refreshCaveTransitionStatus();
                refreshCaveWaypointList();
            });
        }

        const renamePresetBtn = panel.querySelector("#minibia-bot-cave-preset-rename");
        if (renamePresetBtn) {
            renamePresetBtn.addEventListener("click", () => {
                const select = document.getElementById("minibia-bot-cave-preset-select");
                if (!select)
                    return;
                const oldName = select.value;
                if (!oldName) {
                    bot.log("No preset selected to rename.");
                    return;
                }
                const newName = window.prompt("Enter new name for preset:", oldName);
                if (newName === null)
                    return; // cancelled
                const trimmed = newName.trim();
                if (!trimmed) {
                    bot.log("Invalid preset name.");
                    return;
                }
                const success = bot.cave.renamePreset(oldName, trimmed);
                if (success) {
                    refreshCavePresetControls();
                    refreshCaveStatus();
                    refreshCaveWaypointList();
                    // Select the new name in dropdown
                    const updatedSelect = document.getElementById("minibia-bot-cave-preset-select");
                    if (updatedSelect) {
                        const options = Array.from(updatedSelect.options);
                        const match = options.find(opt => opt.value === trimmed);
                        if (match)
                            updatedSelect.value = trimmed;
                    }
                    bot.log(`Preset renamed to "${trimmed}"`);
                } else {
                    bot.log("Rename failed. Check for duplicate names.");
                }
            });
        }

        // ---- Export selected preset ----
        const exportPresetBtn = panel.querySelector("#minibia-bot-cave-preset-export");
        if (exportPresetBtn) {
            exportPresetBtn.addEventListener("click", () => {
                const select = document.getElementById("minibia-bot-cave-preset-select");
                const name = select?.value;
                if (!name) {
                    bot.log("No preset selected to export.");
                    return;
                }

                const preset = bot.cave.exportPreset(name);
                if (!preset) {
                    bot.log(`Preset "${name}" could not be exported (not found).`);
                    return;
                }

                const payload = {
                    "minibiaBot.cave.presets": [preset]
                };
                const json = JSON.stringify(payload, null, 2);

                const safeName = preset.name.replace(/[^A-Za-z0-9_.-]/g, "_");
                const blob = new Blob([json], {
                    type: "application/json"
                });
                const url = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = url;
                a.download = `${safeName}.preset.json`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(url), 1000);

                bot.log(
                    `Exported preset "${preset.name}" ` + 
                    `(${preset.route.length} waypoint${preset.route.length === 1 ? "" : "s"}, ` + 
`${preset.transitions.length} transition${preset.transitions.length === 1 ? "" : "s"})`);
            });
        }

        // Route audit is manual/on-demand, with no background scan or timers.
        const caveAuditButton = panel.querySelector('#minibia-bot-cave-audit');
        const caveAuditResult = panel.querySelector('#minibia-bot-cave-audit-result');
        if (caveAuditButton && caveAuditResult) {
            caveAuditButton.addEventListener('click', () => {
                const report = bot.cave?.auditRoute?.();
                if (!report) return;
                const heading = `Audit snapshot: ${report.waypointCount} waypoints, ${report.issueCount} warning${report.issueCount === 1 ? '' : 's'}.`;
                caveAuditResult.textContent = report.issues.length
                    ? [heading, ...report.issues.map(issue =>
                        `${issue.index >= 0 ? `#${issue.index + 1}: ` : ''}${issue.text}`),
                        ...(report.truncated ? ['More warnings omitted.'] : []),
                        'Advisory only; native Pathfinder reachability is not checked.'].join('\n')
                    : `${heading} No structural warnings. Native Pathfinder reachability is not checked.`;
                bot.log(`Cave: ${heading}`);
            });
        }

